<script module lang="ts">
/**
 * Tour.Target: the part a step points at, which adds no box.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tour.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/overlays/tour.module.css'

export interface TourTargetProps {
  /**
   * The name a step's `target` uses.
   */
  name: string
  /**
   * The part the step points at.
   */
  children: Snippet
}
</script>

<script lang="ts">
let { name, children }: TourTargetProps = $props()
const joined = joinSlot(undefined, () => ({ name: name }))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span class={styles.target} data-tour-target={name}>{@render children?.()}</span
>{/if
}{@render joined.end?.()}
